/** ⚖️ Derives every `4_gate` launch row the repo's own fixtures demand and, with `--write`, appends the
 * missing ones to `.vscode/🧩️launch.seed.jsonc` (re-read immediately before the edit, because peers
 * hold the same file). `.vscode/launch.json` is never touched here — it is regenerated by
 * `@semio-tech/plugin-registry:generate`. */
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, relative, resolve } from "node:path";

const repoRoot = resolve(import.meta.dir, "../../../../../../..");
const seedPath = resolve(repoRoot, ".vscode/🧩️launch.seed.jsonc");

type Row = { source: string; name: string; command: string; order: number };

function walk(root: string, visit: (path: string) => void): void {
  const stack = [root];
  while (stack.length > 0) {
    const directory = stack.pop()!;
    for (const entry of readdirSync(directory, { withFileTypes: true })) {
      const path = join(directory, entry.name);
      if (entry.isSymbolicLink()) continue;
      if (entry.isDirectory()) {
        if (!["node_modules", "🗑️generated", "dist", "target", "🤖️generated"].includes(entry.name)) stack.push(path);
      } else if (entry.name.endsWith(".json")) visit(path);
    }
  }
}

const rows: Row[] = [];
function harvest(source: string, value: unknown): void {
  if (Array.isArray(value)) {
    value.forEach((child) => harvest(source, child));
    return;
  }
  if (!value || typeof value !== "object") return;
  const node = value as Record<string, any>;
  const group = node.launchGroup ?? node.group ?? node.presentation?.group;
  const name = node.launchName ?? node.name;
  const order = node.launchOrder ?? node.order ?? node.presentation?.order;
  if (group === "4_gate" && typeof name === "string" && typeof order === "number") {
    const command = typeof node.launchCommand === "string" ? node.launchCommand : typeof node.nxCommand === "string" ? node.nxCommand : typeof node.target === "string" && !node.target.startsWith("bun ") && source.includes("📚️library") ? `bun nx run @semio-tech/repo-lib:${node.target} --skip-nx-cache` : typeof node.command === "string" ? node.command : "";
    if (command !== "") rows.push({ source, name, command, order });
  }
  for (const child of Object.values(node)) harvest(source, child);
}

for (const root of ["🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library", "🌎️hub"]) {
  walk(resolve(repoRoot, root), (path) => {
    let parsed: unknown;
    try {
      parsed = JSON.parse(readFileSync(path, "utf8"));
    } catch {
      return;
    }
    harvest(relative(repoRoot, path), parsed);
  });
}

const unique = new Map<string, Row>();
for (const row of rows.sort((left, right) => left.order - right.order)) if (!unique.has(row.name)) unique.set(row.name, row);
const seed = Bun.JSONC.parse(readFileSync(seedPath, "utf8")) as { configurations: any[] };
const present = new Set(seed.configurations.map((entry) => entry.name));
const missing = [...unique.values()].filter((row) => !present.has(row.name));
for (const row of missing) console.log(`MISSING ${row.name}\n  order   ${row.order}\n  command ${row.command}\n  source  ${row.source}`);
console.log(`declared=${unique.size} present=${unique.size - missing.length} missing=${missing.length}`);

if (process.argv.includes("--write") && missing.length > 0) {
  const text = readFileSync(seedPath, "utf8");
  const anchor = text.lastIndexOf("\n  ],");
  if (anchor < 0) throw new Error("seed has no configurations terminator");
  const block = missing
    .map((row) => `    {\n      "name": ${JSON.stringify(row.name)},\n      "type": "node-terminal",\n      "request": "launch",\n      "command": ${JSON.stringify(row.command)},\n      "cwd": "\${workspaceFolder}",\n      "presentation": {\n        "group": "4_gate",\n        "order": ${row.order}\n      }\n    }`)
    .join(",\n");
  writeFileSync(seedPath, `${text.slice(0, anchor)},\n${block}${text.slice(anchor)}`, "utf8");
  console.log(`WROTE ${missing.length} row(s)`);
}
